<?php defined('BASEPATH') or exit('No direct script access allowed'); $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); $section=$native_project_section??['title'=>'Projeto','columns'=>[],'rows'=>[]]; ?>
